"""Exact original15 hashing/Set generators and literal branch; test-only oracle.

Source literals are frozen before migration, never imported from a prior candidate.
Each replacement records actual calls, including nested algorithms.
"""
from contextlib import ExitStack,contextmanager
from unittest.mock import patch
from chaos import hash_maps as maps,set_runtime as sets

HASH_SOURCE='def hash(self, value, depth=0):\n        from chaos.language import ResourceLimit\n        from chaos.tuple_values import TupleValue\n        from chaos.objects import ChaosInstance, owned as object_owned\n        from chaos.numeric_values import Fraction, Complex, Decimal\n        from chaos.set_values import SetValue, _fingerprint\n        self.step()\n        if depth > 100: raise ResourceLimit(\'Hash key depth exceeds 100\')\n        identity = id(value)\n        if identity in self.active: error(\'Hash keys cannot contain cycles\')\n        if identity in self.memo:\n            result = self.memo[identity][1]\n            if depth + result[2] > 100: raise ResourceLimit(\'Hash key depth exceeds 100\')\n            return result\n        if type(value) is ChaosInstance:\n            object_owned(value, self.evaluator); object_owned(value.klass, self.evaluator)\n            return ((yield from self.instance(value)), False, 0)\n        if type(value) is TupleValue:\n            if len(value) > MAX_ENTRIES: raise ResourceLimit(\'Hash key Tuple exceeds 10000 items\')\n            self.active.add(identity)\n            parts = []\n            try:\n                for child in value: parts.append((yield from self.hash(child, depth+1)))\n            finally: self.active.remove(identity)\n            result = (int.from_bytes(_fingerprint(\'tuple-hash\', tuple(_encoded(child[0]) for child in parts)), \'big\'),\n                      all(child[1] for child in parts), 1+max((child[2] for child in parts), default=-1))\n        elif type(value) is SetValue:\n            from chaos.set_runtime import owned as set_owned\n            set_owned(value,self.evaluator)\n            if value.owner is not None:\n                parts=[(row[2],False,0) for row in value._mapping.entries]\n            else:\n                self.active.add(identity)\n                try:\n                    parts=[]\n                    for child in value:parts.append((yield from self.hash(child,depth+1)))\n                finally:self.active.remove(identity)\n            result=(int.from_bytes(_fingerprint(\'set-hash\',tuple(sorted(_encoded(child[0]) for child in parts))),\'big\'),\n                    value.owner is None,1+max((child[2] for child in parts),default=-1))\n        elif type(value) in (type(None), bool, int, float, str, Fraction, Complex, Decimal):\n            native = self.pure.key(value, depth)\n            result = (int.from_bytes(native.fingerprint, \'big\'), True, native.height)\n        else:\n            error(\'Unhashable value; keys require native immutable values or an Instance hash protocol\', \'unhashable_type\')\n        if result[1]: self.memo[identity] = (value, result)\n        return result\n\ndef instance(self, value):\n        from chaos.language import ResourceLimit\n        from chaos.objects import member_value, special_method, require_callable\n        from chaos.set_values import _fingerprint\n        hash_member = None; hash_position = eq_position = None\n        for position, base in enumerate(value.klass.mro):\n            self.evaluator.tick()\n            if hash_position is None and \'__hash__\' in base.members:\n                hash_position, hash_member = position, base.members[\'__hash__\']\n            if eq_position is None and \'__eq__\' in base.members: eq_position = position\n        if hash_position is None:\n            if eq_position is not None: error(\'An equality override requires an explicit __hash__\', \'unhashable_type\')\n            return int.from_bytes(_fingerprint(\'identity\', (_encoded(_identity(self.evaluator, value)),)), \'big\')\n        if eq_position is not None and eq_position < hash_position:\n            error(\'An equality override must explicitly retain or replace its inherited __hash__\', \'unhashable_type\')\n        if member_value(hash_member) is None: error(\'__hash__ = null makes the Instance unhashable\', \'unhashable_type\')\n        function = yield from self.evaluator._s_access_result(special_method(value, \'__hash__\', self.evaluator))\n        require_callable(function, self.evaluator, setter=True)\n        result = yield from self.evaluator._s_invoke(function, [], synchronous=True)\n        self.evaluator.tick()\n        if type(result) is not int: error(\'__hash__ must synchronously return an exact Int\', value=result)\n        if result.bit_length() > 14000: raise ResourceLimit(\'__hash__ Int exceeds 14000 bits\')\n        return result\n\ndef hash_value(evaluator, value):\n    from chaos.indexing import validate_owned\n    validate_owned(evaluator, value)\n    return (yield from _HashBudget(evaluator).hash(value))[0]\n\ndef _find(evaluator, mapping, key, fingerprint):\n    from chaos.class_creation import project_value\n    from chaos.operators import equal as value_equal\n    for index in mapping.buckets.get(fingerprint, ()):\n        evaluator.tick()\n        stored = mapping.entries[index][0]\n        if stored is key: return index\n        # User equality receives actual identities. A narrowed view must never\n        # pass a hidden, wider opaque key into a callback that can retain it.\n        left = project_key(evaluator, stored, mapping)\n        right = project_key(evaluator, key, mapping)\n        if (yield from value_equal(evaluator, left, right, synchronous=True)): return index\n    return None\n\ndef _store(evaluator, mapping, key, value):\n    from chaos.class_creation import validate_value\n    from chaos.language import ResourceLimit\n    validate_value(evaluator, key); validate_value(evaluator, value)\n    fingerprint = yield from hash_value(evaluator, key)\n    position = yield from _find(evaluator, mapping, key, fingerprint)\n    entries = list(mapping.entries)\n    if position is None:\n        if len(entries) >= MAX_ENTRIES: raise ResourceLimit(\'HashMap exceeds 10000 entries\')\n        entries.append((key, value, fingerprint))\n    else:\n        original, previous, old_hash = entries[position]\n        entries[position] = (original, value, old_hash)\n    return make(evaluator, entries, mapping.capabilities)\n\ndef add(self, evaluator, key, value):\n        from chaos.class_creation import validate_value\n        from chaos.language import ResourceLimit\n        validate_value(evaluator, key); validate_value(evaluator, value)\n        fingerprint = yield from hash_value(evaluator, key)\n        position = yield from _find(evaluator, self, key, fingerprint)\n        if position is None:\n            if len(self.entries) >= MAX_ENTRIES: raise ResourceLimit(\'HashMap exceeds 10000 entries\')\n            self.buckets.setdefault(fingerprint, []).append(len(self.entries))\n            self.entries.append((key, value, fingerprint))\n        else:\n            original, previous, old_hash = self.entries[position]\n            self.entries[position] = (original, value, old_hash)\n\ndef construct(evaluator, entries):\n    from chaos.language import ResourceLimit\n    from chaos.tuple_values import TupleValue\n    cursor = yield from evaluator.suspension.iteration.acquire(entries, temporary=True)\n    if cursor.busy: error(\'HashMap input iterator cannot be re-entered\')\n    cursor.busy = True\n    builder, consumed = _Builder(evaluator), 0\n    try:\n        while True:\n            step = yield from evaluator.suspension.iteration.step(cursor, locked=True)\n            if step[\'done\']: return make(evaluator, builder.entries, builder.capabilities)\n            if consumed >= MAX_ENTRIES: raise ResourceLimit(\'hash_map input exceeds 10000 pairs\')\n            consumed += 1\n            pair = step[\'value\']\n            if type(pair) not in (list, TupleValue) or len(pair) != 2:\n                error(\'hash_map entries require List or Tuple pairs of length 2\')\n            yield from builder.add(evaluator, pair[0], pair[1])\n    finally: cursor.busy = False\n\ndef equal(evaluator, left, right):\n    """Ordinary mapping equality is effectful and independent of entry order."""\n    from chaos.agent_tools import scope\n    from chaos.class_creation import project_value\n    from chaos.operators import equal as value_equal\n    owned(left, evaluator); owned(right, evaluator)\n    if left is right: return True\n    if len(left) != len(right): return False\n    with scope(evaluator, intersection(left.capabilities, right.capabilities)):\n        for key, value, fingerprint in left.entries:\n            evaluator.tick()\n            query = project_key(evaluator, key, left)\n            # Stored insertion hashes are deliberately reused, never silently\n            # rehashing user keys during equality of persistent versions.\n            index = yield from _find(evaluator, right, query, fingerprint)\n            if index is None: return False\n            other = right.entries[index][1]\n            if not (yield from value_equal(evaluator, project_value(evaluator, value, left),\n                                          project_value(evaluator, other, right), synchronous=True)):\n                return False\n    return True\n\ndef resolve(evaluator, request):\n    from chaos.agent_tools import scope\n    from chaos.class_creation import project_value\n    if request.operation == \'hash\': return (yield from hash_value(evaluator, request.key))\n    if request.operation == \'create\': return (yield from construct(evaluator, request.value))\n    mapping = owned(request.mapping, evaluator)\n    with scope(evaluator, mapping.capabilities):\n        if request.operation == \'set\': return (yield from _store(evaluator, mapping, request.key, request.value))\n        fingerprint = yield from hash_value(evaluator, request.key)\n        position = yield from _find(evaluator, mapping, request.key, fingerprint)\n        if request.operation == \'has\': return position is not None\n        if request.operation == \'remove\':\n            return make(evaluator, tuple(entry for index, entry in enumerate(mapping.entries) if index != position), mapping.capabilities)\n        if request.operation in (\'get\', \'index\'):\n            if position is None:\n                if request.operation == \'index\': error(\'HashMap key was not found\', \'key_error\')\n                return project_value(evaluator, request.value, mapping)\n            return project_value(evaluator, mapping.entries[position][1], mapping)\n    error(\'Unknown HashMap operation\')\n'

SET_SOURCE="def add(self,value):\n        from chaos.language import ResourceLimit\n        from chaos.hash_maps import _Builder\n        from chaos.agent_tools import scope\n        if self.attempts>=self.limit:raise ResourceLimit('Set input exceeds '+str(self.limit)+' items')\n        self.attempts+=1;self.items.append(value)\n        if self.table is None and portable(value,self.owner.tick):\n            self.pure.add(value);return\n        account(value,self.pure.budget)\n        with scope(self.owner,self.capabilities):\n            if self.table is None:\n                self.table=_Builder(self.owner)\n                for item in self.pure.items:yield from self.table.add(self.owner,item,None)\n            yield from self.table.add(self.owner,value,None)\n\ndef mapping(evaluator,value):\n    from chaos.hash_maps import _Builder,make\n    owned(value,evaluator)\n    if value.owner is not None:return value._mapping\n    draft=_Builder(evaluator)\n    for item in value.items:yield from draft.add(evaluator,item,None)\n    return make(evaluator,draft.entries)\n\ndef contains(evaluator,value,item):\n    from chaos.set_values import set_contains\n    from chaos.hash_maps import hash_value,_find\n    from chaos.agent_tools import scope\n    owned(value,evaluator)\n    if value.owner is None and portable(item,evaluator.tick):return set_contains(value,item,evaluator.tick)\n    with scope(evaluator,value.capabilities):\n        table=yield from mapping(evaluator,value)\n        fingerprint=yield from hash_value(evaluator,item)\n        return (yield from _find(evaluator,table,item,fingerprint)) is not None\n\ndef algebra(evaluator,operation,left,right):\n    from chaos.set_values import set_binary,set_equal,set_is_disjoint\n    from chaos.hash_maps import _find,make,intersection,project_key\n    from chaos.agent_tools import scope\n    from chaos.language import ResourceLimit\n    owned(left,evaluator);owned(right,evaluator)\n    if left.owner is None and right.owner is None:\n        if operation=='==':return set_equal(left,right,evaluator.tick)\n        if operation=='disjoint':return set_is_disjoint(left,right,evaluator.tick)\n        return set_binary(operation,left,right,evaluator.tick)\n    ceiling=intersection(left.capabilities,right.capabilities)\n    with scope(evaluator,ceiling):\n        a=yield from mapping(evaluator,left);b=yield from mapping(evaluator,right)\n        if operation=='==' and len(a)!=len(b):return False\n        if operation in ('>','>='):a,b=b,a;operation='<' if operation=='>' else '<='\n        if operation in ('<','<=') and (len(a)>len(b) or operation=='<' and len(a)==len(b)):return False\n        rows=[]\n        for key,unused,fingerprint in a.entries:\n            evaluator.tick()\n            query=project_key(evaluator,key,a)\n            present=False if operation=='|' else (yield from _find(evaluator,b,query,fingerprint)) is not None\n            if operation in ('==','<','<=') and not present:return False\n            if operation=='disjoint' and present:return False\n            if operation=='|' or operation=='&' and present or operation in ('-','^') and not present:\n                rows.append((key,None,fingerprint))\n        if operation in ('==','<','<=','disjoint'):return True\n        if operation in ('|','^'):\n            for key,unused,fingerprint in b.entries:\n                evaluator.tick();query=project_key(evaluator,key,b)\n                if (yield from _find(evaluator,a,query,fingerprint)) is None:rows.append((key,None,fingerprint))\n        if len(rows)>10000:raise ResourceLimit('Set exceeds 10000 members')\n        return freeze(evaluator,make(evaluator,rows,ceiling))\n\ndef update(evaluator,operation,value,item):\n    from chaos.set_values import set_add,set_discard\n    from chaos.hash_maps import _store,_find,hash_value,make\n    from chaos.agent_tools import scope\n    owned(value,evaluator)\n    if value.owner is None and portable(item,evaluator.tick):\n        return (set_add if operation=='add' else set_discard)(value,item,evaluator.tick)\n    with scope(evaluator,value.capabilities):\n        table=yield from mapping(evaluator,value)\n        if operation=='add':return freeze(evaluator,(yield from _store(evaluator,table,item,None)))\n        fingerprint=yield from hash_value(evaluator,item)\n        found=yield from _find(evaluator,table,item,fingerprint)\n        rows=tuple(row for index,row in enumerate(table.entries) if index!=found)\n        return freeze(evaluator,make(evaluator,rows,value.capabilities))\n\ndef resolve(evaluator,request):\n    if request.operation in ('add','discard'):return (yield from update(evaluator,request.operation,request.value,request.other))\n    if request.operation=='disjoint':return (yield from algebra(evaluator,'disjoint',request.value,request.other))\n    raise RuntimeError('Unknown Set request')\n"

LITERAL_SOURCE="def source_set(self,node,env,tail=False,**options):\n    from chaos.language import ResourceLimit\n    from chaos.capture_frames import active as capture_active\n    capture=capture_active(self)\n    self.tick()\n    if not node[1] or len(node[1]) > 10000: raise ResourceLimit('Set 字面量需要 1–10000 项')\n    from chaos.set_runtime import Builder\n    from chaos.capture_frames import active,retain\n    builder = Builder(self)\n    retain(active(self),builder)\n    for item in node[1]:\n                    if item[0] == 'spread':\n                        source = yield from self._s_evaluate(item[1], env)\n                        yield from self.suspension.iteration.consume(source, 'set', initial=builder, limit=10000-builder.attempts)\n                    else:\n                        if builder.attempts >= 10000: raise ResourceLimit('Set 输入超过 10000 项')\n                        yield from builder.add((yield from self._s_evaluate(item, env)))\n    return builder.finish()\n"

HASH_TARGETS=(('_HashBudget','hash'),('_HashBudget','instance'),(None,'hash_value'),(None,'_find'),(None,'_store'),('_Builder','add'),(None,'construct'),(None,'equal'),(None,'resolve'))
SET_TARGETS=(('Builder','add'),(None,'mapping'),(None,'contains'),(None,'algebra'),(None,'update'),(None,'resolve'))

@contextmanager
def reference():
    from chaos.language import Evaluator
    from chaos import language
    from chaos.execution_hash_collections import SetLiteralEvaluationFrame
    hash_namespace=dict(vars(maps));set_namespace=dict(vars(sets));literal_namespace={}
    exec(compile(HASH_SOURCE,__file__+':original_hash','exec'),hash_namespace)
    exec(compile(SET_SOURCE,__file__+':original_set','exec'),set_namespace)
    exec(compile(LITERAL_SOURCE,__file__+':original_literal','exec'),literal_namespace)
    reached={};replacements=[]
    for module,namespace,targets,prefix in ((maps,hash_namespace,HASH_TARGETS,'hash'),(sets,set_namespace,SET_TARGETS,'set')):
        for owner,name in targets:
            key=prefix+':'+(owner+'.' if owner else '')+name;reached[key]=0;function=namespace[name]
            def called(*args,_function=function,_key=key,**kwargs):
                reached[_key]+=1;return _function(*args,**kwargs)
            target=getattr(module,owner)if owner else module
            replacements.append((target,name,called))
            if owner is None:namespace[name]=called
    reached['source:set']=0;execute=Evaluator._s_execute
    def old_execute(self,node,env,*args,**kwargs):
        if node[0]=='set':
            reached['source:set']+=1;return literal_namespace['source_set'](self,node,env,*args,**kwargs)
        return execute(self,node,env,*args,**kwargs)
    with ExitStack()as stack:
        for target,name,function in replacements:stack.enter_context(patch.object(target,name,function))
        # language keeps a first-import resolver alias; replace that actual
        # gateway too, so old-mode never executes a migrated Set resolver.
        stack.enter_context(patch.object(language,'set_resolve',set_namespace['resolve']))
        stack.enter_context(patch.object(SetLiteralEvaluationFrame,'KINDS',set()))
        stack.enter_context(patch.object(Evaluator,'_s_execute',old_execute))
        yield reached
